#!/bin/sh
# Render every assets/backgrounds/*.svg to a 3840x2160 PNG and publish the newest as stock.png.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/render-backgrounds.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'render-backgrounds.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu

usage() {
	cat <<'USAGE'
Usage: render-backgrounds.sh [--help|-h] [--build|--version] [--out DIR]

Render every assets/backgrounds/*.svg to DIR/<name>.png at 3840x2160 with inkscape
(falling back to magick), then copy the newest-version one to DIR/stock.png.

Options:
  --out DIR        output directory (default: target/backgrounds under the repo root)
  --build, --version  print this script's build id and exit
  -h, --help       print this help and exit

Exit status: 0 on success; 1 when neither inkscape nor magick is installed or a render fails;
2 on bad usage.
USAGE
}

here=$(dirname "$(readlink -f "$0")")
root=$(dirname "$here")

# scripts/lib/build-id.sh is bash-only (local, BASH_SOURCE), so this is its sh equivalent.
build_id() {
	sha=$(git --no-optional-locks -C "$root" log -1 --format=%H -- "$root" 2>/dev/null) || sha=
	[ -n "$sha" ] || { echo unknown; return 0; }
	st=$(git --no-optional-locks -C "$root" status --porcelain --untracked-files=no -- "$root" 2>/dev/null) || st=
	if [ -n "$st" ]; then echo "$sha-dirty"; else echo "$sha"; fi
}

out=$root/target/backgrounds
for a in "$@"; do
	case $a in
		--help | -h) usage; exit 0 ;;
	esac
done
for a in "$@"; do
	case $a in
		--build | --version) build_id; exit 0 ;;
	esac
done
while [ $# -gt 0 ]; do
	case $1 in
		--out)
			[ $# -ge 2 ] || { echo "render-backgrounds.sh: --out needs a directory" >&2; exit 2; }
			out=$2
			shift 2
			;;
		*) echo "render-backgrounds.sh: unknown argument: $1" >&2; usage >&2; exit 2 ;;
	esac
done

if command -v inkscape >/dev/null 2>&1; then
	tool=inkscape
elif command -v magick >/dev/null 2>&1; then
	tool=magick
else
	echo "render-backgrounds.sh: neither inkscape nor magick is installed" >&2
	exit 1
fi

mkdir -p "$out"
for svg in "$root"/assets/backgrounds/*.svg; do
	[ -e "$svg" ] || { echo "render-backgrounds.sh: no SVGs in $root/assets/backgrounds" >&2; exit 1; }
	name=$(basename "$svg" .svg)
	png=$out/$name.png
	if [ "$tool" = inkscape ]; then
		inkscape "$svg" --export-type=png --export-filename="$png" -w 3840 -h 2160 >/dev/null 2>&1 ||
			{ echo "render-backgrounds.sh: inkscape failed on $svg" >&2; exit 1; }
	else
		magick -background none -density 96 "$svg" -resize 3840x2160! "$png" ||
			{ echo "render-backgrounds.sh: magick failed on $svg" >&2; exit 1; }
	fi
	echo "rendered $png"
done
# Glob order is lexicographic (cde-0.10 sorts before cde-0.7), so pick the newest by version sort.
newest=$(for svg in "$root"/assets/backgrounds/*.svg; do basename "$svg" .svg; done | sort -V | tail -n 1)
cp "$out/$newest.png" "$out/stock.png"
echo "stock.png <- $newest.png"
